package com.remo.app

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Test
import java.io.File

/**
 * Builds the AI tool setup snippets and compares them with the ones the web
 * app produced (fixtures/mcp/client-examples.expected.json, regenerated by
 * apps/web mcp-clients.test.ts).
 */
class McpClientExamplesTest {
    private fun fixture(): File {
        var directory: File? = File("").absoluteFile
        while (directory != null) {
            val candidate = File(directory, "fixtures/mcp/client-examples.expected.json")
            if (candidate.isFile) return candidate
            directory = directory.parentFile
        }
        error("fixtures/mcp/client-examples.expected.json not found")
    }

    @Test fun matchesTheSnippetsEveryPlatformShows() {
        val expected = JSONObject(fixture().readText()).getJSONArray("examples")
        val actual = buildMcpClientExamples("https://remo.example.test/api/mcp", "rm_" + "Ab1-_".repeat(8) + "abc")
        assertEquals(expected.length(), actual.size)
        actual.forEachIndexed { index, example ->
            val item = expected.getJSONObject(index)
            assertEquals(item.getString("name"), example.name)
            assertEquals(item.getString("location"), example.location)
            assertEquals(item.getString("snippet"), example.snippet)
        }
    }
}
